export const FOUNDATION_MIGRATION_SQL = "-- Contractor GenOffice — Foundation Schema (PostgreSQL)\n-- Migration 0001: identity, organization/tenant, membership, workspace,\n-- project, audit, revision framework.\n--\n-- Foundation tables ONLY. No Commercial/Programme/BIM/Goals tables.\n-- (Phase 1 section 16: \"Only establish foundation tables required by this phase.\")\n--\n-- Every tenant-scoped table carries `tenant_id`. Every repository query\n-- enforces `WHERE ... AND tenant_id = $...`. (Phase 1 section 7.)\n--\n-- audit_events: append-only. The repository exposes NO update/delete.\n-- revisions: finalized/superseded rows are immutable. The repository\n--   enforces this (no update/delete for non-draft rows).\n\n-- ────────────────────────────────────────────────────────────\n-- Users (identity)\n-- ────────────────────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS users (\n  id           TEXT PRIMARY KEY,\n  email        TEXT UNIQUE,\n  display_name TEXT,\n  status       TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled')),\n  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- ────────────────────────────────────────────────────────────\n-- AuthProvider bindings (Genspark, OIDC, SAML, password, ...)\n-- A user may have multiple bindings. (provider, subject) is globally unique.\n-- ────────────────────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS auth_provider_bindings (\n  id           TEXT PRIMARY KEY,\n  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  provider     TEXT NOT NULL,\n  subject      TEXT NOT NULL,\n  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),\n  last_used_at TIMESTAMPTZ,\n  UNIQUE (provider, subject)\n);\nCREATE INDEX IF NOT EXISTS idx_auth_bindings_user ON auth_provider_bindings(user_id);\n\n-- ────────────────────────────────────────────────────────────\n-- Organizations (the Tenant). tenant_id == id.\n-- ────────────────────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS organizations (\n  id         TEXT PRIMARY KEY,\n  tenant_id  TEXT NOT NULL,  -- == id; denormalized for uniform tenant scoping\n  name       TEXT NOT NULL,\n  slug       TEXT NOT NULL,\n  status     TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled')),\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (slug)\n);\n\n-- ────────────────────────────────────────────────────────────\n-- Memberships (User x Organization with Role)\n-- Membership is EXPLICIT. (Phase 1 section 5/11.)\n-- ────────────────────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS memberships (\n  id              TEXT PRIMARY KEY,\n  user_id         TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  tenant_id       TEXT NOT NULL,  -- == organization_id; for uniform tenant scoping\n  role            TEXT NOT NULL CHECK (role IN ('owner','admin','member','viewer')),\n  status          TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','revoked')),\n  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (user_id, organization_id)\n);\nCREATE INDEX IF NOT EXISTS idx_memberships_user ON memberships(user_id);\nCREATE INDEX IF NOT EXISTS idx_memberships_tenant ON memberships(tenant_id);\n\n-- ────────────────────────────────────────────────────────────\n-- Workspaces (organizational container inside a Tenant; owns Projects)\n-- ────────────────────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS workspaces (\n  id              TEXT PRIMARY KEY,\n  tenant_id       TEXT NOT NULL,\n  organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  name            TEXT NOT NULL,\n  created_at      TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_workspaces_tenant ON workspaces(tenant_id);\n\n-- ────────────────────────────────────────────────────────────\n-- Projects (canonical business identity). ONE model.\n-- Referenced by future domain authorities (EstimateRevision, etc.)\n-- via project_id. No OfficeProject/ProgrammeProject/etc. (Phase 1 §8.)\n-- ────────────────────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS projects (\n  id           TEXT PRIMARY KEY,\n  tenant_id    TEXT NOT NULL,\n  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,\n  name         TEXT NOT NULL,\n  status       TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','archived')),\n  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_projects_tenant ON projects(tenant_id);\nCREATE INDEX IF NOT EXISTS idx_projects_workspace ON projects(workspace_id);\n\n-- ────────────────────────────────────────────────────────────\n-- Audit events (append-only). NO update/delete from the repository.\n-- (Phase 1 section 12; ADR-0005 Decision 6.)\n-- ────────────────────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS audit_events (\n  event_id    TEXT PRIMARY KEY,\n  tenant_id   TEXT NOT NULL,\n  actor_id    TEXT NOT NULL,\n  actor_kind  TEXT NOT NULL CHECK (actor_kind IN ('user','service')),\n  timestamp   TIMESTAMPTZ NOT NULL DEFAULT now(),\n  action      TEXT NOT NULL,\n  entity_type TEXT NOT NULL,\n  entity_id   TEXT NOT NULL,\n  operation   TEXT NOT NULL,\n  metadata    JSONB\n);\nCREATE INDEX IF NOT EXISTS idx_audit_tenant ON audit_events(tenant_id);\nCREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_events(tenant_id, entity_type, entity_id);\nCREATE INDEX IF NOT EXISTS idx_audit_timestamp ON audit_events(tenant_id, timestamp DESC);\n\n-- Block UPDATE and DELETE on audit_events at the database level.\n-- (Defense in depth — the repository also exposes no update/delete.)\nCREATE OR REPLACE FUNCTION block_audit_mutation() RETURNS TRIGGER AS $$\nBEGIN\n  RAISE EXCEPTION 'audit_events is append-only: UPDATE and DELETE are forbidden';\nEND;\n$$ LANGUAGE plpgsql;\nDROP TRIGGER IF EXISTS trg_block_audit_update ON audit_events;\nDROP TRIGGER IF EXISTS trg_block_audit_delete ON audit_events;\nCREATE TRIGGER trg_block_audit_update BEFORE UPDATE ON audit_events\n  FOR EACH ROW EXECUTE FUNCTION block_audit_mutation();\nCREATE TRIGGER trg_block_audit_delete BEFORE DELETE ON audit_events\n  FOR EACH ROW EXECUTE FUNCTION block_audit_mutation();\n\n-- ────────────────────────────────────────────────────────────\n-- Revisions (generic revision framework). Domain-specific payload is\n-- NOT stored here — this is the metadata infrastructure for immutable\n-- historical truth. (Phase 1 section 13.)\n--\n-- finalized/superseded rows are IMMUTABLE. The repository enforces this\n-- (no update/delete for non-draft rows). A trigger provides defense in depth.\n-- ────────────────────────────────────────────────────────────\n-- C2: revisions are historical authority. They must NEVER be destroyed by\n-- a parent (project/workspace/org) deletion. The FK to projects uses\n-- ON DELETE RESTRICT — a project with revisions cannot be hard-deleted.\n-- (Phase 1.1 C2 fix.)\nCREATE TABLE IF NOT EXISTS revisions (\n  revision_id       TEXT PRIMARY KEY,\n  tenant_id         TEXT NOT NULL,\n  project_id        TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,\n  authority_kind    TEXT NOT NULL,\n  revision_number   INTEGER NOT NULL,\n  status            TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','finalized','superseded')),\n  created_by        TEXT NOT NULL,\n  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),\n  algorithm_version TEXT NOT NULL,\n  content_hash      TEXT NOT NULL,\n  parent_revision_id TEXT REFERENCES revisions(revision_id),\n  finalized_at      TIMESTAMPTZ,\n  UNIQUE (tenant_id, project_id, authority_kind, revision_number)\n);\nCREATE INDEX IF NOT EXISTS idx_revisions_tenant ON revisions(tenant_id);\nCREATE INDEX IF NOT EXISTS idx_revisions_project ON revisions(tenant_id, project_id, authority_kind);\n\n-- H1: dedicated revision-number counter. Each (tenant, project, authority_kind)\n-- has a monotonic counter row. Allocation is atomic via UPSERT + RETURNING —\n-- no race window, no serialization failures, no retry needed.\n-- (Phase 1.1 H1 fix: replaces SELECT MAX(revision_number)+1 under READ COMMITTED.)\nCREATE TABLE IF NOT EXISTS revision_counters (\n  tenant_id       TEXT NOT NULL,\n  project_id      TEXT NOT NULL,\n  authority_kind  TEXT NOT NULL,\n  next_number     INTEGER NOT NULL DEFAULT 1,\n  PRIMARY KEY (tenant_id, project_id, authority_kind)\n);\n\n-- C1: finalized/superseded revisions are IMMUTABLE except for the\n-- controlled status transition finalized->superseded (and draft->superseded,\n-- draft->finalized). The trigger enforces that ONLY `status` (and\n-- `finalized_at` during draft->finalized) may change; every identity/content\n-- field is frozen once finalized. (Phase 1.1 C1 fix.)\n--\n-- Immutable fields (must not change after finalization):\n--   revision_id, tenant_id, project_id, authority_kind, revision_number,\n--   created_by, created_at, algorithm_version, content_hash,\n--   parent_revision_id\n-- Mutable fields (controlled lifecycle only):\n--   status (draft->finalized, draft->superseded, finalized->superseded)\n--   finalized_at (set when draft->finalized; unchanged thereafter)\nCREATE OR REPLACE FUNCTION block_immutable_revision_update() RETURNS TRIGGER AS $$\nBEGIN\n  -- From draft: any field may change (working state).\n  IF OLD.status = 'draft' THEN\n    RETURN NEW;\n  END IF;\n\n  -- From finalized: only the finalized->superseded transition is allowed,\n  -- and ONLY the status field may change. Every other field must be identical.\n  IF OLD.status = 'finalized' THEN\n    IF NEW.status = 'superseded' THEN\n      -- Verify NO field other than status changed.\n      IF NEW.revision_id IS DISTINCT FROM OLD.revision_id\n         OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id\n         OR NEW.project_id IS DISTINCT FROM OLD.project_id\n         OR NEW.authority_kind IS DISTINCT FROM OLD.authority_kind\n         OR NEW.revision_number IS DISTINCT FROM OLD.revision_number\n         OR NEW.created_by IS DISTINCT FROM OLD.created_by\n         OR NEW.created_at IS DISTINCT FROM OLD.created_at\n         OR NEW.algorithm_version IS DISTINCT FROM OLD.algorithm_version\n         OR NEW.content_hash IS DISTINCT FROM OLD.content_hash\n         OR NEW.parent_revision_id IS DISTINCT FROM OLD.parent_revision_id\n         OR NEW.finalized_at IS DISTINCT FROM OLD.finalized_at THEN\n        RAISE EXCEPTION 'revision % is finalized: only status may change during finalized->superseded (identity/content fields are immutable)', OLD.revision_id;\n      END IF;\n      RETURN NEW;\n    END IF;\n    -- Any other transition from finalized is forbidden.\n    RAISE EXCEPTION 'revision % is finalized: UPDATE forbidden (only finalized->superseded is allowed)', OLD.revision_id;\n  END IF;\n\n  -- From superseded: terminal state. No UPDATE at all.\n  IF OLD.status = 'superseded' THEN\n    RAISE EXCEPTION 'revision % is superseded (terminal): UPDATE forbidden', OLD.revision_id;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\nDROP TRIGGER IF EXISTS trg_block_immutable_rev_update ON revisions;\nCREATE TRIGGER trg_block_immutable_rev_update BEFORE UPDATE ON revisions\n  FOR EACH ROW EXECUTE FUNCTION block_immutable_revision_update();\n\n-- Block DELETE on finalized/superseded revisions (defense in depth).\nCREATE OR REPLACE FUNCTION block_immutable_revision_delete() RETURNS TRIGGER AS $$\nBEGIN\n  IF OLD.status IN ('finalized','superseded') THEN\n    RAISE EXCEPTION 'revision % is immutable (status=%): DELETE forbidden', OLD.revision_id, OLD.status;\n  END IF;\n  RETURN OLD;\nEND;\n$$ LANGUAGE plpgsql;\nDROP TRIGGER IF EXISTS trg_block_immutable_rev_delete ON revisions;\nCREATE TRIGGER trg_block_immutable_rev_delete BEFORE DELETE ON revisions\n  FOR EACH ROW EXECUTE FUNCTION block_immutable_revision_delete();\n";

export const COMMERCIAL_MIGRATION_SQL = "-- Contractor GenOffice — Commercial Schema (PostgreSQL)\n-- Migration 0002: PlanMeasurement, BOQ, BOQItem, EstimateRevision payload, Bid.\n--\n-- Commercial persistence ONLY. No application services, no HTTP, no UI.\n-- (Phase 2B.1.)\n--\n-- Reuses the foundation revision infrastructure:\n--   - revisions table (generic RevisionMetadata)\n--   - revision_counters table (atomic revision number allocation)\n--   - immutability triggers on revisions (block UPDATE/DELETE on finalized/superseded)\n--\n-- The EstimateRevision = generic RevisionMetadata + EstimateRevisionPayload.\n-- The payload is stored as canonical immutable JSONB in estimate_revision_payloads.\n-- JSONB is the canonical authority; denormalized fields are indexed projections only.\n--\n-- Tenant enforcement: every table carries tenant_id and every query enforces it.\n-- Historical authority: RESTRICT on FKs that protect EstimateRevision/Bid.\n-- (Phase 2B.1 §6, §16, §21.)\n\n-- ────────────────────────────────────────────────────────────\n-- PlanMeasurement (measurement evidence — NOT commercial authority)\n-- ────────────────────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS plan_measurements (\n  measurement_id            TEXT PRIMARY KEY,\n  tenant_id                 TEXT NOT NULL,\n  project_id                TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,\n  source_artifact_id        TEXT NOT NULL,\n  source_artifact_hash      TEXT NOT NULL,\n  sheet_id                  TEXT,\n  sheet_revision            TEXT,\n  element_reference         TEXT NOT NULL,\n  quantity_value             NUMERIC(20,4) NOT NULL,\n  quantity_unit              TEXT NOT NULL,\n  measurement_method        TEXT NOT NULL CHECK (measurement_method IN ('manual-takeoff','auto-takeoff','ai-proposed','imported')),\n  measurement_basis         TEXT NOT NULL CHECK (measurement_basis IN ('count','length','area','volume','mass','time')),\n  measurement_engine_version TEXT NOT NULL,\n  actor_id                  TEXT NOT NULL,\n  measured_at               TIMESTAMPTZ NOT NULL,\n  provisional               BOOLEAN NOT NULL DEFAULT false,\n  created_at                TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_pm_tenant ON plan_measurements(tenant_id);\nCREATE INDEX IF NOT EXISTS idx_pm_project ON plan_measurements(tenant_id, project_id);\nCREATE INDEX IF NOT EXISTS idx_pm_artifact ON plan_measurements(tenant_id, source_artifact_id);\n\n-- ────────────────────────────────────────────────────────────\n-- BOQ (scope structure — NOT commercial authority)\n-- ────────────────────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS boqs (\n  boq_id     TEXT PRIMARY KEY,\n  tenant_id  TEXT NOT NULL,\n  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,\n  name       TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_boqs_tenant ON boqs(tenant_id);\nCREATE INDEX IF NOT EXISTS idx_boqs_project ON boqs(tenant_id, project_id);\n\n-- BOQItem (scope line within a BOQ)\nCREATE TABLE IF NOT EXISTS boq_items (\n  item_id                TEXT PRIMARY KEY,\n  boq_id                 TEXT NOT NULL REFERENCES boqs(boq_id) ON DELETE CASCADE,\n  tenant_id              TEXT NOT NULL,\n  item_code              TEXT NOT NULL,\n  description            TEXT NOT NULL,\n  unit                   TEXT NOT NULL,\n  quantity_value          NUMERIC(20,4) NOT NULL,\n  quantity_unit           TEXT NOT NULL,\n  provenance             TEXT NOT NULL CHECK (provenance IN ('plan-measurement','imported','manual')),\n  source_measurement_ids  JSONB,\n  created_at             TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_boq_items_tenant ON boq_items(tenant_id);\nCREATE INDEX IF NOT EXISTS idx_boq_items_boq ON boq_items(boq_id);\n\n-- ────────────────────────────────────────────────────────────\n-- EstimateRevision payload (canonical immutable commercial content)\n--\n-- The EstimateRevisionPayload is stored as JSONB — the canonical authority.\n-- Denormalized fields (currency, target_profit_mode) are indexed projections\n-- for queryability ONLY; they are NOT a second authority.\n--\n-- The revision_id FK references the generic revisions table (which stores\n-- RevisionMetadata + immutability triggers). The payload_json is immutable\n-- once the revision is finalized; a trigger blocks mutation.\n-- (Phase 2B.1 §6, §7, §8.)\n-- ────────────────────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS estimate_revision_payloads (\n  revision_id          TEXT PRIMARY KEY REFERENCES revisions(revision_id) ON DELETE RESTRICT,\n  tenant_id             TEXT NOT NULL,\n  project_id            TEXT NOT NULL,\n  payload_json          JSONB NOT NULL,\n  -- Denormalized index fields (NOT canonical — derived from payload_json)\n  currency              CHAR(3) NOT NULL,\n  target_profit_mode    TEXT NOT NULL,\n  target_profit_ratio   NUMERIC(6,5) NOT NULL,\n  created_at            TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_erp_tenant ON estimate_revision_payloads(tenant_id);\nCREATE INDEX IF NOT EXISTS idx_erp_project ON estimate_revision_payloads(tenant_id, project_id);\n\n-- Immutability trigger: block UPDATE/DELETE on finalized/superseded payloads.\n-- The generic revisions trigger protects the revisions table; this trigger\n-- protects the payload JSONB. (Phase 2B.1 §8, §33.)\n--\n-- For draft status, the function returns NEW (allow the UPDATE — drafts are\n-- working state). For finalized/superseded, it raises (mutation forbidden).\n-- Returning OLD for draft status would silently discard every payload UPDATE,\n-- causing stored content_hash / payload_json drift — a serious correctness bug.\n-- (Phase 2B.2 trigger correctness fix.)\nCREATE OR REPLACE FUNCTION block_estimate_payload_mutation() RETURNS TRIGGER AS $$\nDECLARE\n  rev_status TEXT;\nBEGIN\n  SELECT status INTO rev_status FROM revisions WHERE revision_id = OLD.revision_id;\n  IF rev_status IN ('finalized', 'superseded') THEN\n    RAISE EXCEPTION 'estimate revision payload % is immutable (revision status=%): mutation forbidden', OLD.revision_id, rev_status;\n  END IF;\n  -- draft status: allow the UPDATE to proceed with the new row.\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_block_erp_update ON estimate_revision_payloads;\nCREATE TRIGGER trg_block_erp_update BEFORE UPDATE ON estimate_revision_payloads\n  FOR EACH ROW EXECUTE FUNCTION block_estimate_payload_mutation();\n\nDROP TRIGGER IF EXISTS trg_block_erp_delete ON estimate_revision_payloads;\nCREATE TRIGGER trg_block_erp_delete BEFORE DELETE ON estimate_revision_payloads\n  FOR EACH ROW EXECUTE FUNCTION block_estimate_payload_mutation();\n\n-- ────────────────────────────────────────────────────────────\n-- Bid (commercial submission decision — references finalized EstimateRevision)\n-- ────────────────────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS bids (\n  bid_id                          TEXT PRIMARY KEY,\n  tenant_id                       TEXT NOT NULL,\n  project_id                      TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,\n  estimate_revision_id            TEXT NOT NULL REFERENCES revisions(revision_id) ON DELETE RESTRICT,\n  estimate_revision_content_hash  TEXT NOT NULL,\n  status                          TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','submitted','won','lost','withdrawn')),\n  final_price_minor                BIGINT,\n  final_price_currency             CHAR(3),\n  director_adjustment_minor        BIGINT,\n  director_adjustment_currency      CHAR(3),\n  adjustment_rationale             TEXT,\n  submitted_at                     TIMESTAMPTZ,\n  outcome_at                       TIMESTAMPTZ,\n  outcome_note                     TEXT,\n  created_at                       TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_bids_tenant ON bids(tenant_id);\nCREATE INDEX IF NOT EXISTS idx_bids_project ON bids(tenant_id, project_id);\nCREATE INDEX IF NOT EXISTS idx_bids_revision ON bids(tenant_id, estimate_revision_id);\n";

export const MAGIC_LINKS_MIGRATION_SQL = "-- ────────────────────────────────────────────────────────────────────────────\n-- 0003_magic_links.sql — passwordless email magic-link auth tokens (Phase 2C.2)\n--\n-- ADR-0009 Decision 3: production auth is passwordless email magic-link.\n-- The browser posts an email to /api/auth/request-link; the server generates\n-- a single-use, short-lived HMAC-signed token, stores it here, and emails it.\n-- On verify, the token is consumed (used_at set) and a session cookie issued.\n--\n-- This migration is ADDITIVE — it does NOT modify 0001_foundation.sql or\n-- 0002_commercial.sql. The frozen architecture is unchanged.\n-- ────────────────────────────────────────────────────────────────────────────\n\nCREATE TABLE IF NOT EXISTS magic_links (\n  token_hash      TEXT PRIMARY KEY,          -- SHA-256 of the token (we never store the raw token)\n  email           TEXT NOT NULL,             -- the email the link was sent to\n  expires_at      TIMESTAMPTZ NOT NULL,      -- short-lived (default 15 minutes)\n  used_at         TIMESTAMPTZ,               -- NULL until consumed; single-use enforced\n  created_at      TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Index for lookup by token_hash (the verify path).\nCREATE INDEX IF NOT EXISTS idx_magic_links_token_hash ON magic_links(token_hash) WHERE used_at IS NULL;\n\n-- Index for periodic cleanup of expired tokens.\nCREATE INDEX IF NOT EXISTS idx_magic_links_expires_at ON magic_links(expires_at);\n";

export const AUTH_MIGRATION_SQL = "-- ────────────────────────────────────────────────────────────────────────────\n-- 0004_auth.sql — password auth + waitlist (Phase 2C.3, additive)\n--\n-- ADR-0009 D3 (magic-link) is supplemented by password auth for the admin\n-- and approved users. The waitlist captures sign-up requests; the admin\n-- approves them to create real accounts.\n--\n-- This migration is ADDITIVE — it does NOT modify 0001/0002/0003.\n-- ────────────────────────────────────────────────────────────────────────────\n\n-- Add password_hash to users (nullable — null for magic-link-only users)\nALTER TABLE users ADD COLUMN IF NOT EXISTS password_hash TEXT;\n\n-- Add is_demo flag to users (for demo accounts with quick-login)\nALTER TABLE users ADD COLUMN IF NOT EXISTS is_demo BOOLEAN NOT NULL DEFAULT false;\n\n-- Waitlist table\nCREATE TABLE IF NOT EXISTS waitlist (\n  id              TEXT PRIMARY KEY,\n  email           TEXT NOT NULL UNIQUE,\n  status          TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),\n  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n  approved_by     TEXT REFERENCES users(id),\n  approved_at     TIMESTAMPTZ,\n  created_user_id TEXT REFERENCES users(id),\n  display_name    TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_waitlist_status ON waitlist(status);\n";
